class UnionEditorModel : CompEditorModel<Union> {

	private static readonly long serialVersionUID = 1L;
	private static readonly int LENGTH = 0;
	private static readonly int MNEMONIC = 1;
	private static readonly int DATATYPE = 2;
	private static readonly int FIELDNAME = 3;
	private static readonly int COMMENT = 4;
	private static readonly int ORDINAL = 5;

	private List<TableColumn> hiddenColumns;

	UnionEditorModel(UnionEditorProvider provider, bool showInHex) : base(provider)
    {
		headers = new string[] { "Length", "Mnemonic", "DataType", "Name", "Comment" };
		columnWidths = new int[] { 75, 100, 100, 100, 150 };
		columnOffsets = new int[headers.length];
		adjustOffsets();
		this.showHexNumbers = showInHex;

		List<TableColumn> additionalColumns = new();
		TableColumn ordinalColumn = new TableColumn(ORDINAL, 75);
		ordinalColumn.setHeaderRenderer(new GTableHeaderRenderer());
		ordinalColumn.setHeaderValue("Ordinal");
		additionalColumns.add(ordinalColumn);
		hiddenColumns = Collections.unmodifiableList(additionalColumns);
	}

	/* @Override */
	public string getTypeName() {
		return "Union";
	}

